#!/usr/bin/env python3
"""Generate supabase/seed.sql from content/ (catalogue + items + exam sets). No student/teacher data."""
import json, os, glob
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
J = lambda p: json.load(open(os.path.join(ROOT, p), encoding="utf-8"))
def q(v):
    if v is None: return "null"
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, (int, float)): return str(v)
    if isinstance(v, (list, dict)): return q(json.dumps(v, ensure_ascii=False)) + "::jsonb"
    return "'" + str(v).replace("'", "''") + "'"
def arr(xs, t="text"): return "array[" + ",".join(q(x) for x in xs) + f"]::{t}[]" if xs else f"'{{}}'::{t}[]"
cur = J("content/curriculum.json"); out = ["-- GENERATED by tools/build_seed.py — do not edit by hand", "begin;",
  "delete from public.answers; delete from public.attempts; delete from public.exam_sets; delete from public.items; delete from public.strands; delete from public.subjects; delete from public.grades;"]
counts = {}
for g in cur["grades"]:
    out.append(f"insert into public.grades (code,name_th,app_name,sort,status,external_url,room_max) values ({q(g['code'])},{q(g['short'])},{q('Exam Gym ปิยมิตรมัธยม '+g['short'])},{g['sort']},{q(g['status'])},{q(g.get('external_url'))},10);")
    for s in g["subjects"]:
        out.append(f"insert into public.subjects (id,grade_code,code,name_th,icon,color,course_codes,status,note,sort) values ({q(s['id'])},{q(g['code'])},{q(s['code'])},{q(s['name'])},{q(s['icon'])},{q(s['color'])},{arr(s['course_codes'])},{q(s['status'])},{q(s.get('note'))},{s['sort']});")
        for i, t in enumerate(s["strands"]):
            out.append(f"insert into public.strands (id,subject_id,grade_code,code,name_th,group_no,group_name,concepts,course_code,term,source,status,sort) values ({q(t['id'])},{q(s['id'])},{q(g['code'])},{q(t['id'].split('-')[-1])},{q(t['name'])},{t['no']},{q(('บทที่ ' if g['code']!='M6' else 'สาระที่ ')+str(t['no'])+' '+t['name'])},{q(t['concepts'])},{q(t.get('course_code'))},{q(t.get('term'))},{q(t['source'])},{q(t['status'])},{i+1});")
strand_ids = {t["id"] for g in cur["grades"] for s in g["subjects"] for t in s["strands"]}
# ม.1–ม.5 original drafts
for f in sorted(glob.glob(os.path.join(ROOT, "content/items/m*.json"))):
    d = json.load(open(f, encoding="utf-8"))
    for it in d["items"]:
        sid = f"{it['grade']}-{it['subject']}"; tid = f"{sid}-T{it['topic_no']:02d}"
        assert tid in strand_ids, f"{it['id']}: strand {tid} not in curriculum"
        out.append("insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,hint,explanation,origin,status,no_shuffle,source_label,review_flag) values ("
                   + ",".join([q(it["id"]), q(it["grade"]), q(sid), q(tid), q(it["course_code"]), "2", str(it["level"]), q(it["question"]), q(it["choices"]), str(it["answer"]),
                               arr([it["answer"]], "smallint"), q(it.get("hint")), q(it["explanation"]), q("draft_original"), q("draft"), q(it["no_shuffle"]), q(it["source"]), q(it.get("review_flag"))]) + ");")
        counts[(it["grade"], it["subject"], "draft")] = counts.get((it["grade"], it["subject"], "draft"), 0) + 1
# ม.6 imported AS-IS
man = J("content/m6/m6_manifest.json"); m6 = J("content/m6/m6_items.json")
IMG = "https://kruom9.github.io/kruom-cefr/examgym/m6-ios/data/img/"
for r in m6:
    it = r["item"]; sid = f"M6-{r['subject']}"; tid = f"{sid}-S{it['sara']}"; assert tid in strand_ids, tid
    free = it["key"] == "free"   # ทปอ. ให้คะแนนทุกคน → every choice accepted (ม.6 isRight rule)
    keys = list(range(len(it["choices"]))) if free else [k - 1 for k in it["key"]]
    media = {k: it[k] for k in ("img", "table", "after", "topic", "n") if k in it}
    if free: media["key_free"] = True
    if "img" in it: media["img_url"] = IMG + it["img"]
    out.append("insert into public.items (id,grade_code,subject_id,strand_id,course_code,term,difficulty,stem,choices,answer_index,answer_keys,explanation,choice_notes,media,origin,status,no_shuffle,shuffle_reason,source_label,exam_year,legacy_id) values ("
               + ",".join([q(f"M6-{r['subject']}-{it['id']}"), q("M6"), q(sid), q(tid), q(next(b['exam_code'] for b in man['banks'] if b['id']==r['bank'])), "null", "2", q(it["stem"]), q(it["choices"]), str(keys[0]),
                           arr(keys, "smallint"), q([it["k"]]), q(it.get("e")), q(media or None), q("imported_m6"), q("imported"), q(r["no_shuffle"]), q(r["shuffle_reason"]),
                           q(it.get("f") or f"Exam Gym ม.6 · {man['source']['commit'][:7]}"), q(it.get("year")), q(r["bank"] + ":" + it["id"])]) + ");")
    counts[("M6", r["subject"], "imported")] = counts.get(("M6", r["subject"], "imported"), 0) + 1
# exam sets
for g in cur["grades"]:
    live = [s for s in g["subjects"] if s["status"] == "live" and counts.get((g["code"], s["code"], "draft"))]
    if g["code"] != "M6":
        for s in live:
            # room exam: 20 items, mix [4,6,6,4] by level; subjects with fewer drafts get a smaller, honest paper
            lvc = [0, 0, 0, 0]
            for it in json.load(open(os.path.join(ROOT, "content", "items", g["code"].lower() + ".json"), encoding="utf-8"))["items"]:
                if it["subject"] == s["code"]: lvc[it["level"]] += 1
            mix = [min(m, c) for m, c in zip([4, 6, 6, 4], lvc)]
            n_room = min(20, sum(lvc)); mix_room = mix
            out.append(f"insert into public.exam_sets (id,grade_code,subject_id,kind,name_th,n_items,minutes,mix,max_attempts,pass_pct,unlock_rule,shuffle_choices,sort) values ({q(g['code']+'-ROOM-'+s['code'])},{q(g['code'])},{q(s['id'])},'subject_room',{q('ห้องสอบวิชา'+s['name'])},{n_room},{45 if n_room >= 20 else 36},{q(mix_room)},5,70,{q({'mastery_pct':70})},false,{s['sort']});")
        if live:
            out.append(f"insert into public.exam_sets (id,grade_code,subject_id,kind,name_th,n_items,per_subject,minutes,mix,max_attempts,pass_pct,unlock_rule,shuffle_choices,sort) values ({q(g['code']+'-MOCK')},{q(g['code'])},null,'mock','สอบเสมือนจริง',{10*len(live)},10,90,{q([2,3,3,2])},5,70,{q({'per_subject_answered':10})},false,99);")
    else:
        # fixed papers from the ม.6 banks (unchanged id lists), shuffle_choices = true (ม.6 rule)
        import re, subprocess
        for b in man["banks"]:
            js = open(os.path.join(ROOT, "content/m6/banks", b["file"]), encoding="utf-8").read()
            bank = json.loads(subprocess.check_output(["node", "-e", "global.window={};eval(require('fs').readFileSync(0,'utf8'));const k=Object.keys(window)[0];process.stdout.write(JSON.stringify(window[k].mocks||[]))"], input=js.encode()))
            full = max(len(m.get('ids') or []) for m in bank)
            for i, m in enumerate(bank):
                ids = m.get('ids') or []   # empty = ม.6 'mmix' paper drawn by the ม.6 app's own rule
                out.append(f"insert into public.exam_sets (id,grade_code,subject_id,kind,name_th,n_items,minutes,mix,max_attempts,pass_pct,unlock_rule,shuffle_choices,item_ids,sort) values ({q('M6-'+b['subject']+'-'+m['id'])},'M6',{q('M6-'+b['subject'])},'mock',{q(m['name'])},{len(ids) or full},{q(m.get('min'))},{q([0,0,0,0])},null,70,{q({} if ids else {'draw':'m6_app_mmix'})},true,{arr(['M6-'+b['subject']+'-'+x for x in ids]) if ids else 'null'},{i+1});")
out.append("commit;")
open(os.path.join(ROOT, "supabase/seed.sql"), "w", encoding="utf-8").write("\n".join(out) + "\n")
json.dump({f"{k[0]}-{k[1]}-{k[2]}": v for k, v in sorted(counts.items())}, open(os.path.join(ROOT, "content/counts.json"), "w"), indent=1)
print(len(out), "statements ·", sum(v for k, v in counts.items() if k[2]=="draft"), "draft ·", sum(v for k, v in counts.items() if k[2]=="imported"), "imported")
